using CallingBell.Api.Models;using Microsoft.EntityFrameworkCore;namespace CallingBell.Api.Data;public sealed class CallingBellDbContext(DbContextOptions<CallingBellDbContext> options):DbContext(options){public DbSet<Category> Categories=>Set<Category>();public DbSet<Business> Businesses=>Set<Business>();public DbSet<TrendingService> TrendingServices=>Set<TrendingService>();public DbSet<NearbyBusiness> NearbyBusinesses=>Set<NearbyBusiness>();public DbSet<Banner> Banners=>Set<Banner>();protected override void OnModelCreating(ModelBuilder m){m.Entity<Category>().ToTable("Categories").HasKey(x=>x.Id);m.Entity<Business>().ToTable("Businesses").HasKey(x=>x.Id);m.Entity<TrendingService>().ToTable("TrendingServices").HasKey(x=>x.Id);m.Entity<NearbyBusiness>().ToTable("NearbyBusinesses").HasKey(x=>x.Id);m.Entity<Banner>().ToTable("Banners").HasKey(x=>x.Id);}}